const activeScript = "<script>(function(){const nav=document.getElementById('uwNav');if(!nav)return;const path=location.pathname;const routeFor=p=>p==='/wheels'||p.startsWith('/wheels/')?'/wheels':p.startsWith('/configure/')?'/custom-wheel-builder':p;const active=routeFor(path);nav.querySelectorAll('a').forEach(a=>{a.removeAttribute('aria-current');if(a.getAttribute('href')===active)a.setAttribute('aria-current','page')})})();</script>";
const interactionScript = "<script>(function(){\nconst nav=document.getElementById('uwNav'),menu=document.getElementById('uwMenu'),lang=document.getElementById('uwLanguage');\nconst closeMenu=()=>{if(nav&&menu){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='MENU'}};\nif(menu&&nav){menu.addEventListener('click',()=>{const open=!nav.classList.contains('open');nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'CLOSE':'MENU'});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.addEventListener('click',e=>{if(nav.classList.contains('open')&&!nav.contains(e.target)&&!menu.contains(e.target))closeMenu()});window.addEventListener('resize',()=>{if(window.innerWidth>900)closeMenu()})}\nif(lang)lang.addEventListener('click',()=>{const zh=document.documentElement.lang!=='zh';document.documentElement.lang=zh?'zh':'en';document.querySelectorAll('[data-en][data-zh]').forEach(el=>{el.innerHTML=el.getAttribute(zh?'data-zh':'data-en')});lang.textContent=zh?'中文 / EN':'EN / 中文'});\ndocument.querySelectorAll('.field,.form-field').forEach((field,index)=>{const label=field.querySelector('label'),control=field.querySelector('input:not([type=hidden]),select,textarea');if(label&&control&&!control.labels?.length){if(!control.id)control.id='uw-field-'+index;label.htmlFor=control.id}});\ndocument.querySelectorAll('select').forEach((select,index)=>{\nif(select.dataset.uwEnhanced||select.classList.contains('native-select-hidden'))return;select.dataset.uwEnhanced='true';const wrap=document.createElement('div');wrap.className='uw-select';select.parentNode.insertBefore(wrap,select);wrap.appendChild(select);select.classList.add('uw-select-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');\nconst id='uw-select-'+(select.id||index),trigger=document.createElement('button');trigger.type='button';trigger.className='uw-select-trigger';trigger.id=id+'-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls',id+'-menu');if(select.required)trigger.setAttribute('aria-required','true');const associatedLabel=select.labels?.[0]||select.closest('.field,.form-field,.field-group')?.querySelector('label')||select.parentElement?.querySelector('label');if(associatedLabel){if(!associatedLabel.id)associatedLabel.id=id+'-label';trigger.setAttribute('aria-labelledby',associatedLabel.id)}else if(select.getAttribute('aria-label'))trigger.setAttribute('aria-label',select.getAttribute('aria-label'));const describedBy=[select.getAttribute('aria-describedby'),id+'-error'].filter(Boolean).join(' ');trigger.setAttribute('aria-describedby',describedBy);\nconst label=document.createElement('span'),caret=document.createElement('span');caret.className='uw-select-caret';caret.setAttribute('aria-hidden','true');trigger.append(label,caret);const list=document.createElement('div');list.className='uw-select-menu';list.id=id+'-menu';list.setAttribute('role','listbox');list.hidden=true;wrap.append(trigger,list);\nconst error=document.createElement('span');error.className='uw-select-error';error.id=id+'-error';error.setAttribute('role','alert');error.hidden=true;error.textContent='Please select an option.';wrap.append(error);\nconst close=()=>{list.hidden=true;trigger.setAttribute('aria-expanded','false')};\nconst sync=()=>{const selected=select.options[select.selectedIndex];label.textContent=selected?selected.textContent.trim():'Select an option';trigger.disabled=select.disabled;if(select.value){trigger.removeAttribute('aria-invalid');error.hidden=true}list.querySelectorAll('[role=option]').forEach((item,i)=>item.setAttribute('aria-selected',String(i===select.selectedIndex)))};\nconst render=()=>{const selected=select.options[select.selectedIndex];label.textContent=selected?selected.textContent.trim():'Select an option';trigger.disabled=select.disabled;list.innerHTML='';[...select.options].forEach((option,i)=>{const item=document.createElement('button');item.type='button';item.className='uw-select-option';item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));item.disabled=option.disabled;item.textContent=option.textContent.trim();item.addEventListener('click',()=>{if(option.disabled)return;select.selectedIndex=i;select.dispatchEvent(new Event('change',{bubbles:true}));sync();close();trigger.focus()});list.append(item)})};\ntrigger.addEventListener('click',()=>{const open=list.hidden;document.querySelectorAll('.uw-select-menu').forEach(m=>m.hidden=true);document.querySelectorAll('.uw-select-trigger').forEach(b=>b.setAttribute('aria-expanded','false'));list.hidden=!open;trigger.setAttribute('aria-expanded',String(open));if(open){const target=list.querySelector('[aria-selected=true]:not(:disabled)')||list.querySelector('[role=option]:not(:disabled)');if(target)target.focus()}});\ntrigger.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Enter',' '].includes(e.key)){e.preventDefault();if(list.hidden)trigger.click();else list.querySelector('[role=option]:not(:disabled)')?.focus()}});\nlist.addEventListener('keydown',e=>{const opts=[...list.querySelectorAll('[role=option]:not(:disabled)')],i=opts.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close();trigger.focus()}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();opts[Math.max(0,Math.min(opts.length-1,i+(e.key==='ArrowDown'?1:-1)))]?.focus()}else if(e.key==='Home'){e.preventDefault();opts[0]?.focus()}else if(e.key==='End'){e.preventDefault();opts[opts.length-1]?.focus()}});\nselect.addEventListener('change',sync);wrap.addEventListener('focusout',e=>{if(!wrap.contains(e.relatedTarget))close()});new MutationObserver(render).observe(select,{childList:true,subtree:true,attributes:true});render();\nselect.addEventListener('invalid',e=>{e.preventDefault();trigger.setAttribute('aria-invalid','true');error.hidden=false;trigger.focus()});\nconst form=select.closest('form');if(form&&select.required)form.addEventListener('submit',e=>{if(!select.disabled&&!select.value){e.preventDefault();trigger.setAttribute('aria-invalid','true');error.hidden=false;trigger.focus()}else{trigger.removeAttribute('aria-invalid');error.hidden=true}},true);if(form)form.addEventListener('reset',()=>queueMicrotask(()=>{sync();error.hidden=true;trigger.removeAttribute('aria-invalid')}));\n});\ndocument.addEventListener('click',e=>{if(!e.target.closest('.uw-select')){document.querySelectorAll('.uw-select-menu').forEach(m=>m.hidden=true);document.querySelectorAll('.uw-select-trigger').forEach(b=>b.setAttribute('aria-expanded','false'))}});\n})();</script>";

