function greatCircle(a,b,steps=100){const rad=d=>d*Math.PI/180,deg=r=>r*180/Math.PI;const toVec=p=>{const lat=rad(p[0]),lon=rad(p[1]);return [Math.cos(lat)*Math.cos(lon),Math.cos(lat)*Math.sin(lon),Math.sin(lat)];};const A=toVec(a),B=toVec(b),dot=Math.max(-1,Math.min(1,A[0]*B[0]+A[1]*B[1]+A[2]*B[2])),omega=Math.acos(dot),sin=Math.sin(omega),out=[];for(let i=0;i<=steps;i++){const t=i/steps;let v;if(Math.abs(sin)<1e-8)v=A.map((n,j)=>n*(1-t)+B[j]*t);else v=A.map((n,j)=>n*Math.sin((1-t)*omega)/sin+B[j]*Math.sin(t*omega)/sin);const norm=Math.hypot(...v);v=v.map(n=>n/norm);let lon=deg(Math.atan2(v[1],v[0]));if(out.length){const prev=out[out.length-1][1];while(lon-prev>180)lon-=360;while(lon-prev< -180)lon+=360;}out.push([deg(Math.asin(v[2])),lon]);}return out;}
