async function roadRoute(a,b){try{const url='https://router.project-osrm.org/route/v1/driving/'+a[1]+','+a[0]+';'+b[1]+','+b[0]+'?overview=full&geometries=geojson';const r=await fetch(url);if(!r.ok)throw new Error('route');const d=await r.json();const coords=d.routes?.[0]?.geometry?.coordinates||[];return coords.map(p=>[p[1],p[0]]);}catch(e){return [];}}
