function localDateAt(date,tz){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const get=t=>parts.find(p=>p.type===t)?.value;return {year:Number(get('year')),month:Number(get('month')),day:Number(get('day')),iso:get('year')+'-'+get('month')+'-'+get('day')};}
