 const destinationRoad=await roadRoute(airport.point,dest);if(run!==mapRunId)return;if(destinationRoad.length){addRoute(destinationRoad,'#198038','4 5');mapStatus('Stage 3/3 · Destination airport → customer address · 1–3 days');await animateVehicle(destinationRoad,'truck','Destination airport → customer address · 1–3 days',run);}if(run!==mapRunId)return;revealDeliveryStage(3);
