const submitScript = "<script>\n(function(){\nconst API=\"https://enobstpmthgraiozgncg.supabase.co/rest/v1/wheel_enquiries\";\nconst KEY=\"sb_publishable_5XYSwJKcZB5g61IbgOsvPA_ja2iAsFG\";\nasync function submit(form,config,kind,button,status){\n const data=new FormData(form),name=String(data.get(kind===\"dealer_application\"?\"contact\":\"name\")||\"\").trim(),email=String(data.get(\"email\")||\"\").trim(),message=String(data.get(kind===\"dealer_application\"?\"needs\":\"message\")||\"\").trim();\n status.className=\"form-status\";status.textContent=\"\";\n if(data.get(\"fax\")){status.textContent=\"Thank you. Your enquiry has been received.\";status.classList.add(\"success\");form.reset();return;}\n if(!form.reportValidity())return;\n if(Date.now()-Number(form.dataset.openedAt||0)<1800){status.textContent=\"Please review your details and try again.\";status.classList.add(\"error\");return;}\n if(!name||!email||!message){status.textContent=\"Please complete all required fields.\";status.classList.add(\"error\");return;}\n button.disabled=true;button.textContent=\"SUBMITTING…\";status.textContent=\"Submitting your enquiry securely…\";\n const reference=\"UW-\"+(kind===\"dealer_application\"?\"B2B\":\"CON\")+\"-\"+new Date().toISOString().slice(0,10).replaceAll(\"-\",\"\")+\"-\"+crypto.randomUUID().slice(0,8).toUpperCase();\n const row={reference_id:reference,request_type:kind,customer_name:name,customer_email:email,notes:message,configuration:config(data),attachments:[]};\n try{\n  const response=await fetch(API,{method:\"POST\",headers:{apikey:KEY,Authorization:\"Bearer \"+KEY,\"Content-Type\":\"application/json\",Prefer:\"return=minimal\"},body:JSON.stringify(row)});\n  if(!response.ok)throw new Error(\"Submission failed (\"+response.status+\"). Please try again or use the wheel configurator.\");\n  form.reset();status.textContent=\"Thank you. Your enquiry has been received. Reference: \"+reference+\". Our team can follow up using the email you provided.\";status.classList.add(\"success\");\n }catch(error){status.textContent=error.message||\"Unable to submit. Please try again.\";status.classList.add(\"error\");}\n finally{button.disabled=false;button.textContent=kind===\"dealer_application\"?\"SUBMIT PARTNERSHIP ENQUIRY ↗\":\"SEND ENQUIRY ↗\";}\n}\nconst dealer=document.getElementById(\"dealerForm\");\nif(dealer){dealer.dataset.openedAt=String(Date.now());dealer.addEventListener(\"submit\",e=>{e.preventDefault();const d=new FormData(dealer);submit(dealer,d=>({source:\"dealers-partnership-page\",company:d.get(\"company\"),website:d.get(\"website\"),country:d.get(\"country\"),business_type:d.get(\"business_type\"),sales_channels:d.get(\"channels\"),annual_volume:d.get(\"annual_volume\"),requirements:d.get(\"needs\")}),\"dealer_application\",document.getElementById(\"dealerSubmit\"),document.getElementById(\"dealerStatus\"));});}\nconst contact=document.getElementById(\"contactForm\");\nif(contact){contact.dataset.openedAt=String(Date.now());contact.addEventListener(\"submit\",e=>{e.preventDefault();const d=new FormData(contact);submit(contact,d=>({source:\"contact-page\",company:d.get(\"company\"),country:d.get(\"country\"),topic:d.get(\"topic\"),message:d.get(\"message\")}),\"contact\",document.getElementById(\"contactSubmit\"),document.getElementById(\"contactStatus\"));});}\n})();\n</script>";
